example_solution:
package hamming

import "errors"

func Distance(a, b string) (d int, err error) {
	if len(b) != len(a) {
		return 0, errors.New("strings of unequal length")
	}
	for i := range len(a) {
		if a[i] != b[i] {
			d++
		}
	}
	return d, err
}

test_code:
package hamming

import "testing"

func TestHamming(t *testing.T) {
	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			got, err := Distance(tc.s1, tc.s2)
			switch {
			case tc.expectError:
				if err == nil {
					t.Fatalf("Distance(%q, %q) expected error, got: %d", tc.s1, tc.s2, got)
				}
			case err != nil:
				t.Fatalf("Distance(%q, %q) returned error: %q, want: %d", tc.s1, tc.s2, err, tc.want)
			case got != tc.want:
				t.Fatalf("Distance(%q, %q) = %d, want %d", tc.s1, tc.s2, got, tc.want)
			}
		})
	}
}

func BenchmarkHamming(b *testing.B) {
	for range b.N {
		for _, tc := range testCases {
			Distance(tc.s1, tc.s2)
		}
	}
}
